/*
 * [演算法說明]
 * 這是一個變種的最長遞增子序列 (Longest Increasing Subsequence, LIS) 問題。
 * 
 * 演算法步驟：
 * 1. 將大象按重量 (W) 從小到大排序。如果重量相同，按 IQ (S) 從大到小排序。
 * 2. 在排序後的序列中，找出一組 IQ (S) 嚴格遞減的子序列。
 * 3. 由於已經按 W 排序且要求 W 嚴格遞增，我們在 LIS 轉移時需檢查 W[i] > W[j] 且 S[i] < S[j]。
 * 4. 使用動態規劃記錄長度和路徑，最後回溯輸出結果。
 */

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Elephant {
    int id, w, s;
};

bool compare(const Elephant& a, const Elephant& b) {
    if (a.w != b.w) return a.w < b.w;
    return a.s > b.s;
}

int main() {
    vector<Elephant> e;
    int w, s, id = 1;
    while (cin >> w >> s) {
        e.push_back({id++, w, s});
    }

    sort(e.begin(), e.end(), compare);

    int n = e.size();
    vector<int> dp(n, 1);
    vector<int> prev(n, -1);
    int max_len = 0, best_idx = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (e[i].w > e[j].w && e[i].s < e[j].s) {
                if (dp[j] + 1 > dp[i]) {
                    dp[i] = dp[j] + 1;
                    prev[i] = j;
                }
            }
        }
        if (dp[i] > max_len) {
            max_len = dp[i];
            best_idx = i;
        }
    }

    cout << max_len << endl;
    vector<int> path;
    for (int i = best_idx; i != -1; i = prev[i]) {
        path.push_back(e[i].id);
    }
    for (int i = path.size() - 1; i >= 0; --i) {
        cout << path[i] << endl;
    }

    return 0;
}
